mapper.select:
SELECT n.NOTIFICATION_ID, n.USERNAME, n.NOTIFICATION_TYPE, n.TITLE, n.MESSAGE, n.RELATED_TYPE, n.RELATED_ID, n.RELATED_URL, n.IS_READ, n.READ_AT, n.CREATED_AT, n.CREATED_BY, u.NAME AS CREATED_BY_NAME FROM TB_NOTIFICATION n LEFT JOIN TB_USER u ON n.CREATED_BY = u.USERNAME WHERE n.USERNAME = #{username}
AND n.IS_READ = 0
ORDER BY n.CREATED_AT DESC LIMIT #{limit} OFFSET #{offset}
